    /// <summary>
    /// Calculates line amount.
    /// </summary>
    /// <param name = "_qty">Qty.</param>
    /// <returns>Amount.</returns>
    public AmountCur calcLineAmount(Qty _qty)
    {
        AmountCur amount = next calcLineAmount(_qty);

        if (PdsGlobal::pdsIsCWItem(this.parmItemId()))
        {
		    SalesLine salesLine = this.parmSalesLine();

            amount = CurrencyExchangeHelper::amount(salesLine.displayMETActualWeight() * this.parmPrice(), this.parmCurrencyCode());
        }

        return amount;
    }

    /// <summary>
    /// Calculates line amount forced.
    /// </summary>
    /// <param name = "_qty">Qty.</param>
    /// <param name = "_checkPolicy">Check policy.</param>
    /// <returns>Amount.</returns>
    public AmountCur calcLineAmountForced(Qty _qty, PriceDiscPolicyCheckPolicy _checkPolicy)
    {
        AmountCur amount = next calcLineAmountForced(_qty, _checkPolicy);

        if (PdsGlobal::pdsIsCWItem(this.parmItemId()))
        {
		    SalesLine salesLine = this.parmSalesLine();

            amount = CurrencyExchangeHelper::amount(salesLine.displayMETActualWeight() * this.parmPrice(), this.parmCurrencyCode());
        }

        return amount;
    }
